window.LANES={"loud":{"name":"Loud","kindWord":"Websites","kind":"site"},"motion":{"name":"Motion","kindWord":"Websites","kind":"site"},"quiet":{"name":"Quiet","kindWord":"Websites","kind":"site"},"direct":{"name":"Direct","kindWord":"Websites","kind":"site"},"broad":{"name":"Broad","kindWord":"Tools","kind":"tool"},"specific":{"name":"Specific","kindWord":"Tools","kind":"tool"}};
window.BUILDS=[{"n":1,"slug":"northgate-quote-engine","kind":"tool","lane":"broad","trade":"Kitchen fitter","mobile":false,"group":"Tools · Broad","name":"Northgate Quote Engine","biz":"Kitchen fitter","c":"#245247","sheet":"#E0E7E5","cInk":"#FFFFFF","cText":"#245247","short":"A quote that assembles itself while the customer answers.","long":"Nine questions. As the customer answers, an isometric kitchen draws itself — cabinets appear, the worktop changes material, the island slides in — and a sticky panel builds the price live. It ends in an itemised quote that prints to A4.","proves":"Turns a \"can you price this up?\" text into a priced job at midnight.","tags":["Generative SVG","Live pricing","Prints to A4"]},{"n":2,"slug":"redgate-job-system","kind":"tool","lane":"broad","trade":"Heating & plumbing","mobile":false,"group":"Tools · Broad","name":"Redgate Job & Lead System","biz":"Heating & plumbing","c":"#3730a3","sheet":"#E3E2F2","cInk":"#FFFFFF","cText":"#3730A3","short":"Every enquiry, where it came from, and what happened to it.","long":"A pipeline at real product density: drag-and-drop kanban, a sortable table, a deal drawer with the full activity timeline, and a Cmd-K palette that searches deals, contacts and commands.","proves":"Nothing lives in your texts any more.","tags":["Kanban + table","Cmd-K palette","CSV export"]},{"n":3,"slug":"halcyon-dispatch","kind":"tool","lane":"broad","trade":"Heating dispatch","mobile":false,"group":"Tools · Broad","name":"Halcyon Dispatch","biz":"Heating dispatch team","c":"#2f5cdb","sheet":"#E2E8FA","cInk":"#FFFFFF","cText":"#2F5CDB","short":"Drag a job to another engineer and the week re-plans itself.","long":"Week and day scheduling for a field team. Drag to reschedule, clashes and capacity overruns flag instantly, SLA countdowns run against the real clock — so the board reads correctly whatever day you open it.","proves":"Six engineers, one screen, no phone calls to find out who is where.","tags":["Drag to reschedule","Clash detection","SLA countdown"]},{"n":4,"slug":"ledgerline","kind":"tool","lane":"broad","trade":"Any trade","mobile":false,"group":"Tools · Broad","name":"Ledgerline","biz":"Invoice & proposal studio","c":"#1f4fd8","sheet":"#E0E6FA","cInk":"#FFFFFF","cText":"#1F4FD8","short":"A live A4 page that reflows as you type.","long":"Invoices and proposals with a real page preview, three templates that genuinely change the layout, money maths done in integer pence, and a print stylesheet that gives you a proper PDF.","proves":"The paperwork stops being a Sunday job.","tags":["Live A4 preview","Aged debt","Print to PDF"]},{"n":5,"slug":"mortgage-lab","kind":"tool","lane":"specific","trade":"Mortgage broker","mobile":false,"group":"Tools · Specific","name":"Mortgage Lab","biz":"Broker lead magnet","c":"#0b6e4f","sheet":"#DDEBE6","cInk":"#FFFFFF","cText":"#0B6E4F","short":"What an overpayment really saves, month by month.","long":"A full amortisation engine behind a scrubber chart. Shows the years and interest an overpayment saves, stress-tests the next remortgage at +1/2/3 points, and compares three saved scenarios side by side.","proves":"The kind of tool people bookmark, then ring you about.","tags":["Amortisation engine","Stress test","Scenarios"]},{"n":6,"slug":"payslip-lab","kind":"tool","lane":"specific","trade":"Accountant","mobile":false,"group":"Tools · Specific","name":"Payslip Lab","biz":"Accountant lead magnet","c":"#2952cc","sheet":"#E1E7F8","cInk":"#FFFFFF","cText":"#2952CC","short":"Gross to net, and the 60% trap nobody explains.","long":"A UK take-home planner: a waterfall from gross to net, a marginal-rate curve that exposes the taper between £100k and £125,140, and employee vs sole trader vs limited company side by side.","proves":"One page that answers the question every new client opens with.","tags":["Waterfall chart","60% trap curve","Reverse solver"]},{"n":7,"slug":"atelier-voss","kind":"site","lane":"quiet","trade":"Architecture practice","mobile":false,"group":"Websites · Quiet","name":"Atelier Voss","biz":"Architecture practice","c":"#14508c","sheet":"#DEE7EF","cInk":"#FFFFFF","cText":"#14508C","short":"A studio site with no photographs at all.","long":"The entire site is illustrated in hand-authored technical drawings: elevations that draw themselves in, hatched plans, dimension lines, poché section cuts. Cyanotype blue, and a real six-cell title block for a masthead.","proves":"What a site looks like when nothing on it came from a stock library.","tags":["All-SVG drawings","Pinned sequence","Title block"]},{"n":8,"slug":"cadence","kind":"site","lane":"direct","trade":"Software company","mobile":false,"group":"Websites · Direct","name":"Cadence","biz":"Field-ops software","c":"#FFB300","sheet":"#FFF4DB","cInk":"#101114","cText":"#8F6709","short":"The page is an operations board that never stops running.","long":"A departure board under tungsten light: the board is the hero, the headline is a card pinned inside it, ETAs flip like split-flap cells, and a whole shift plays out as you scroll. Pricing is a line-items table.","proves":"A product page where the product is the page.","tags":["Self-playing board","Split-flap cells","Signal amber"]},{"n":9,"slug":"maree","kind":"site","lane":"motion","trade":"Fragrance house","mobile":false,"group":"Websites · Motion","name":"MARÉE — Sel Obscur","biz":"Fragrance house","c":"#A9CBBD","sheet":"#F3F8F6","cInk":"#101114","cText":"#61746E","short":"Ink through water, and a page that darkens as you descend.","long":"Salt drawn from a black tide. The ground moves through three marine phases as the notes progress, the bottle is faked entirely in layered SVG, and the whole thing refuses the category’s gold for sea glass.","proves":"Luxury without a single gold gradient.","tags":["Ink canvas","Tone-shifting scroll","SVG glass"]},{"n":10,"slug":"signal","kind":"site","lane":"loud","trade":"Festival","mobile":false,"group":"Websites · Loud","name":"SIGNAL 2027","biz":"Music & light festival","c":"#3B18E0","sheet":"#E4DFFB","cInk":"#FFFFFF","cText":"#3B18E0","short":"Type that reacts to how hard you scroll.","long":"Three days of sound, code and light. Marquees whose speed and skew answer your scrolling, headlines that scramble into place, an RGB fringe on the display type because the identity is light being split, and a live countdown in enormous tabular numerals.","proves":"Loud, and still not a template.","tags":["Scroll-velocity type","RGB fringe","Live countdown"]},{"n":11,"slug":"kerbside-scorecard","kind":"tool","lane":"broad","trade":"Any local business","mobile":false,"group":"Tools · Broad","name":"Kerbside Scorecard","biz":"Google profile report card","c":"#B42318","sheet":"#F5E0DF","cInk":"#FFFFFF","cText":"#B42318","short":"Marks a Google Business Profile like an exam.","long":"Type a business’s numbers — reviews, photos, categories, map rank — and it grades the profile: per-row deductions, the fix for each one, and what the gap is costing per month. Prints as a client-ready report.","proves":"A prospect sees their own grade before you ever pitch.","tags":["Live re-marking","Competitor table","Prints to A4"]},{"n":12,"slug":"stopcock","kind":"tool","lane":"broad","trade":"Any trade","mobile":false,"group":"Tools · Broad","name":"Stopcock","biz":"Missed-call leak meter","c":"#14606E","sheet":"#DEE9EB","cInk":"#FFFFFF","cText":"#14606E","short":"What unanswered calls cost you a year.","long":"Five sliders — calls, missed share, job value, close rate — and it meters the annual leak, where it goes, and what a 60-second text-back recovers. Every assumption is on show, including a gone-for-good factor, so the number survives a sceptic.","proves":"The maths behind the whole offer, in the prospect’s own numbers.","tags":["Animated meter","Call funnel","Honest model"]},{"n":13,"slug":"turnover","kind":"tool","lane":"specific","trade":"Roofer","mobile":false,"group":"Tools · Specific","name":"Turnover","biz":"Roofing firm rebuild","c":"#C77D2B","sheet":"#F7EDE1","cInk":"#101114","cText":"#956025","short":"Drag the tape line across a 2011 site and its rebuild.","long":"The same roofing firm on both sides of a draggable tape line — the old site on one side, the rebuild on the other — then a table of what actually changed. Both sites are drawn in code, not screenshots.","proves":"“Before and after” you can put your hands on.","tags":["Drag reveal","Phone frame","Change table"]},{"n":14,"slug":"fenwick-booking","kind":"tool","lane":"broad","trade":"Heating engineer","mobile":false,"group":"Tools · Broad","name":"Fenwick Booking","biz":"Heating engineer","c":"#B4451F","sheet":"#F5E5E0","cInk":"#FFFFFF","cText":"#A4401E","short":"Service, slot, deposit, confirmed — no phone tag.","long":"Five steps: pick a service, take a slot from a grid generated off the real calendar, leave details, pay a deposit that holds the slot, and see the SMS trail that follows. Demo payment only — the card fields are fixed test values.","proves":"The job is in the diary before you have picked up the phone.","tags":["Live slot grid","Demo deposit","SMS preview"]},{"n":15,"slug":"jobsheet","kind":"tool","lane":"specific","trade":"Any trade with a van","mobile":false,"group":"Tools · Specific","name":"Jobsheet","biz":"Van-side job report","c":"#275C3F","sheet":"#E1E8E4","cInk":"#FFFFFF","cText":"#275C3F","short":"Fill it in from the van, the customer report writes itself.","long":"Work done, before/after photos (uploaded and downscaled on your own phone), guarantee, next service due — and out comes a branded report the customer keeps and forwards. The review ask is built into the last page.","proves":"Every finished job leaves a document with your name on it.","tags":["Live report","Photo upload","Prints to A4"]},{"n":16,"slug":"shiftbook","kind":"tool","lane":"specific","trade":"Hair salon","mobile":false,"group":"Tools · Specific","name":"Shiftbook","biz":"Salon staff rota","c":"#6D3B52","sheet":"#EBE4E7","cInk":"#FFFFFF","cText":"#6D3B52","short":"Click a cell to place a shift. Clashes flag as you go.","long":"Click to roster, clashes flag instantly, hours fill against each contract and run red when over, wage cost totals live at the bottom. Weeks anchor to the real calendar and last week copies in one click.","proves":"The rota stops being a photo of a whiteboard.","tags":["Click to roster","Contract hours","Wage totals"]},{"n":17,"slug":"long-exposure","kind":"site","lane":"motion","trade":"Film production company","mobile":true,"group":"Websites · Motion","name":"Long Exposure","biz":"Long Exposure","c":"#E8A84B","sheet":"#FCF3E6","cInk":"#101114","cText":"#836131","short":"A film company's site that plays like a film you can scrub.","long":"The page opens on a countdown leader and then runs inside a letterboxed gate with a timecode burned into the corner. Scrolling scrubs the cut; pressing play lets it run on its own; three reels swap the whole shot list. Every frame is drawn in code — no video, no images, nothing to buffer.","proves":"You can show a showreel moving without hosting a single video file.","tags":["scroll-driven","canvas","showreel"]},{"n":18,"slug":"overhead","kind":"site","lane":"motion","trade":"Drone survey & filming","mobile":true,"group":"Websites · Motion","name":"Overhead","biz":"Overhead","c":"#B7791F","sheet":"#F5ECE0","cInk":"#101114","cText":"#8A5D1C","short":"Scroll to climb — the valley draws itself in contours as you rise.","long":"The page is an ascent. Scrolling is altitude: the telemetry counts up, a fictional Peak District dale inks itself in from the valley floor to the tops, and by 120 m the whole view has tilted from an oblique into a flat survey sheet. The map is generated in the browser from one height field, so the contours, the dry-stone walls, the hedgerows and the brook all come out of the same arithmetic.","proves":"A survey outfit can show what it actually hands over instead of a gallery of aerial photos.","tags":["scroll-driven","mapping","before-after"]},{"n":19,"slug":"southpaw","kind":"site","lane":"loud","trade":"Boxing club","mobile":true,"group":"Websites · Loud","name":"Southpaw","biz":"Boxing club, Leeds","c":"#C8281E","sheet":"#F7E1E0","cInk":"#FFFFFF","cText":"#B6261D","short":"A boxing club site built as a fight card, run by a round timer.","long":"The hero is a working three-minute round timer — start, pause, reset, twelve rounds with a minute's rest — and every ten seconds it lands another line of the headline like a jab. Classes are laid out as bouts on a fight poster, the timetable is a real weekly grid, and a \"what's on tonight\" row is worked out from the visitor's own clock.","proves":"Somebody who has never boxed can pick a level, pick a night this week and be booked in about twenty seconds.","tags":["Working round timer","Fight-card classes","Live timetable","Free-session flow"]},{"n":20,"slug":"marrow-and-pin","kind":"site","lane":"loud","trade":"Tattoo studio","mobile":true,"group":"Websites · Loud","name":"Marrow & Pin","biz":"Tattoo studio, Bristol","c":"#5B2A86","sheet":"#E8E1EE","cInk":"#FFFFFF","cText":"#5B2A86","short":"A flash wall that inks itself as you scroll past each sheet.","long":"Nine hand-drawn flash designs pinned up as paper sheets, each one drawn twice — a thin purple stencil and the finished black ink — with the ink filling in as the sheet crosses the middle of the screen. Filter the wall by artist, open a sheet for sizes, and the design carries through to a consultation form laid out like the studio's own paperwork, placement picked on a body outline instead of typed into a box.","proves":"Your own drawings can be the website, and they can still take the booking.","tags":["hand-drawn SVG","scroll-driven","booking form"]},{"n":21,"slug":"hale-and-partners","kind":"site","lane":"quiet","trade":"Accountant","mobile":true,"group":"Websites · Quiet","name":"Hale & Partners","biz":"Chartered accountants, Harrogate","c":"#A61E1E","sheet":"#F3E0E0","cInk":"#FFFFFF","cText":"#A61E1E","short":"A year-end that settles, and the deadlines counted from today.","long":"A practice site set out as a well-kept ledger: services written as double entries — what you hand over on the left, what you get back on the right — and a real set of accounts with last year beside this year. The figures count to their values as the statement comes into view and a green tick draws itself beside Filed; the deadline calendar is worked out from the day the visitor opens the page, so it is never out of date.","proves":"The dates and the figures do the selling. Nothing else has to.","tags":["ledger layout","live deadlines","fee request"]},{"n":22,"slug":"fern-physio","kind":"site","lane":"quiet","trade":"Physiotherapy clinic","mobile":true,"group":"Websites · Quiet","name":"Fern Physio","biz":"Fern Physio","c":"#6F8F79","sheet":"#EBEFEC","cInk":"#101114","cText":"#556D5E","short":"A drawn body with ten tappable points, and a booking flow behind it.","long":"A two-room physiotherapy clinic where the hero is a hand-drawn standing figure, front and back, with ten points you can tap. Each one names what the problem usually turns out to be, what the physio would actually do about it, and books that assessment in four questions. The diary is generated from the real clock, so the slots are never stale.","proves":"A visitor can say where it hurts before they have to say anything to a receptionist.","tags":["quiet","booking","drawn SVG"]},{"n":23,"slug":"kestrel-electrical","kind":"site","lane":"direct","trade":"Electrician","mobile":true,"group":"Websites · Direct","name":"Kestrel Electrical","biz":"Two-van electrical firm","c":"#6B3A1E","sheet":"#EAE3E0","cInk":"#FFFFFF","cText":"#6B3A1E","short":"An electrician's page built as a fuse board — every job is a breaker.","long":"Three lines say what they do, where they go and when they answer; under them sit three fields and the phone number at poster size. The services are a row of breakers on a board — flip one and it turns on to show what's included, what it costs and a button to ring about it. The only thing that moves on the page is a switch.","proves":"Someone standing in a dark kitchen can ring the right number in one tap, at any hour, without reading a word of marketing.","tags":["Breaker board","Three-field callback","Postcode area check","Open-now line switching"]},{"n":24,"slug":"kerb-and-camber","kind":"site","lane":"direct","trade":"Garage","mobile":true,"group":"Websites · Direct","name":"Kerb & Camber","biz":"Kerb & Camber MOT Centre","c":"#1F4E9C","sheet":"#E0E6F1","cInk":"#FFFFFF","cText":"#1F4E9C","short":"A UK number plate you type into, and the MOT date that comes back.","long":"An independent MOT and service centre where the hero is a real number plate you can type in. Press Check and a job card slides in with the vehicle, the last advisory, how many days until the MOT runs out, and the next three slots on the ramp. The price board, the tyre-size helper and the opening hours are all on the same page, and the phone number never leaves the screen on a mobile.","proves":"Somebody who does not know when their MOT is due can find out and book it before they close the tab.","tags":["direct","reg lookup","booking"]},{"n":25,"slug":"ringsback","kind":"tool","lane":"broad","trade":"Any service business","mobile":true,"group":"Tools · Broad","name":"Ringsback","biz":"Heating firm, Leeds","c":"#17784A","sheet":"#DFECE6","cInk":"#FFFFFF","cText":"#17784A","short":"Missed-call text-back console: the text goes out, the reply lands here.","long":"A live feed of today's calls — answered, missed, missed then texted then replied then booked — with the exact message that went out and how many seconds after the call it left. Press \"Simulate a missed call\" and you watch the whole thing happen: the phone rings out, a countdown runs, the text sends, and a minute later the customer replies.","proves":"The customer gets a text before they've finished leaving a voicemail.","tags":["Live call feed","Simulated missed call","Editable templates","Recovered report"]},{"n":26,"slug":"starboard","kind":"tool","lane":"broad","trade":"Any local business","mobile":true,"group":"Tools · Broad","name":"Starboard","biz":"Shown running for Aldercroft Tree Care","c":"#B45309","sheet":"#F5E7DD","cInk":"#FFFFFF","cText":"#A44C0A","short":"Asks for the review at the right moment, then helps you reply to it.","long":"Every job finished this week with a status against it — not asked, asked, opened, reviewed — and a timeline showing exactly when each message went. Press \"Ask now\" and you see the text that leaves; a few seconds later the customer opens it and the review turns up at the top of the reviews screen, quietly highlighted.","proves":"You can answer every review you have got in about a minute, and stop forgetting to ask the happy ones.","tags":["Ask-now timeline","Reply desk","Star distribution","Twelve-week trend"]},{"n":27,"slug":"slate","kind":"tool","lane":"broad","trade":"Any service business","mobile":true,"group":"Tools · Broad","name":"Slate","biz":"Ashgrove Building & Maintenance","c":"#3A5A72","sheet":"#E3E8EB","cInk":"#FFFFFF","cText":"#3A5A72","short":"Your own price book, and the estimate it builds in a minute.","long":"Every rate the business charges lives in one book — labour, materials, plant, extras — with cost, markup and sell price side by side and editable in place. Building an estimate is typing a few words and picking lines out of that book; the total, the VAT and the deposit move as you go. The customer gets a real A4 document they can sign with a finger and pay the deposit on.","proves":"The price you agreed on the doorstep and the price on the paperwork are the same price.","tags":["price book","estimates","signature"]},{"n":28,"slug":"triage","kind":"tool","lane":"broad","trade":"Any service business","mobile":true,"group":"Tools · Broad","name":"Triage","biz":"Latchford Locks & Security","c":"#2F5D50","sheet":"#E2E8E7","cInk":"#FFFFFF","cText":"#2F5D50","short":"Every enquiry, every channel, sorted by who has waited longest.","long":"Website form, missed call, WhatsApp, email, Facebook message and the note somebody took on the office phone all land in one list, and the list is ordered by how long the person has been waiting rather than when they arrived. The clock on each one counts up in front of you, turns amber at half an hour and red at an hour, and stops the moment you reply. New enquiries land while you watch, so you can see what an unattended inbox actually costs.","proves":"The enquiry you never got back to is the one at the top of the list, not the one you forgot.","tags":["inbox","response time","board"]},{"n":29,"slug":"doorstep","kind":"tool","lane":"broad","trade":"Any service business","mobile":true,"group":"Tools · Broad","name":"Doorstep","biz":"Heating firm’s customer","c":"#2B4FA2","sheet":"#E1E6F2","cInk":"#FFFFFF","cText":"#2B4FA2","short":"The page the customer opens on their phone after they have booked.","long":"Where the job is, who is coming, the paperwork, what is left to pay and somewhere to ask a question — all on one phone-width page. A business-view panel sits alongside it, and pressing \"On the way\" over there starts the customer's ETA counting down and walks the van along a drawn route line on this side.","proves":"That is one fewer \"what time is he coming?\" phone call, every single job.","tags":["Live ETA countdown","Drawn route line","Demo card payment","Business view"]},{"n":30,"slug":"clockcard","kind":"tool","lane":"broad","trade":"Any service business","mobile":true,"group":"Tools · Broad","name":"Clockcard","biz":"Redgate Works","c":"#2B4C7E","sheet":"#E1E6ED","cInk":"#FFFFFF","cText":"#2B4C7E","short":"Staff clock in from the van; the office watches the week fill up.","long":"Two views of one clock. On a phone the fitter picks the job, taps clock in and gets a running timer, a break button and a note for the office. On the desk it is a week grid of people against days with overtime shaded, every job's hours set against the estimate, and a week that can be approved and exported.","proves":"You find out a job is running over while it is still running, not when the invoice goes out.","tags":["time tracking","two personas","timesheets"]},{"n":31,"slug":"boiler-book","kind":"tool","lane":"specific","trade":"Heating engineer","mobile":true,"group":"Tools · Specific","name":"Boiler Book","biz":"Ashgate Heating","c":"#B4500C","sheet":"#F5E7DD","cInk":"#FFFFFF","cText":"#A44A0D","short":"Thirty boilers sorted by what's due, with the chasing done for you.","long":"A heating engineer's book of every boiler they look after: what is fitted where, when it was last serviced, when it falls due, and the letter, text and call that go out on their own. The service record is filled in on the doorstep with one hand, and completing it moves that row from overdue to fine and sets next year's reminders while the engineer is still on the drive.","proves":"The boiler you serviced last October chases itself this October, whether you remember it or not.","tags":["reminders","service records","heating"]},{"n":32,"slug":"mot-minder","kind":"tool","lane":"specific","trade":"Garage","mobile":true,"group":"Tools · Specific","name":"MOT Minder","biz":"Kilnbrook Motors","c":"#1B4E7D","sheet":"#DFE6ED","cInk":"#FFFFFF","cText":"#1B4E7D","short":"Every car the garage has seen, and the texts that bring them back.","long":"Forty vehicles with their MOT and service dates, last visit and outstanding advisories, sorted by what runs out first. The reminder sequence goes out at six weeks, two weeks and three days with a rebook link in it; when the customer taps that link the slot fills itself and the row flips to booked while you watch. Every advisory the last test threw up can be ticked into a quote and texted from the same screen.","proves":"The car books itself back in while you are under a different one.","tags":["specific","reminders","rebooking"]},{"n":33,"slug":"chairside","kind":"tool","lane":"specific","trade":"Hair salon","mobile":true,"group":"Tools · Specific","name":"Chairside","biz":"Four-chair salon","c":"#7A4A2E","sheet":"#ECE6E2","cInk":"#FFFFFF","cText":"#7A4A2E","short":"Rebooks the client at the counter and refills the slots that fall out.","long":"A real diary for today across four stylists, with checkout on whoever is at the desk. The counter tablet asks \"same again in six weeks?\" with three slots that actually fit, an add-on, a tip and a demo card. Cancel an appointment and the waitlist gets texted; a few seconds later somebody says yes and the slot fills itself back in.","proves":"The gap somebody cancelled at nine is booked again by half past, without anyone picking up the phone.","tags":["Four-stylist diary","Counter rebooking","Deposit shield","Waitlist refill"]},{"n":34,"slug":"turntable","kind":"tool","lane":"specific","trade":"Restaurant","mobile":true,"group":"Tools · Specific","name":"Turntable","biz":"Corncrake","c":"#A9600F","sheet":"#F3E9DD","cInk":"#FFFFFF","cText":"#9A5810","short":"The floor, the queue at the door and the deposit rule, on one screen.","long":"A drawn plan of eighteen tables across the room and the yard, each one showing who is on it, which course they are on and how long they have been sat. Clear a table and the top party on the waitlist that fits it is texted, walks in and is seated, all on the plan in front of you. The book runs alongside it with the deposit rule that catches sixes and Friday nights, and the numbers behind the service — covers, turn times and no-shows by month.","proves":"The table that has just gone gets refilled before anyone has walked past the desk.","tags":["specific","live board","waitlist"]},{"n":35,"slug":"roofline","kind":"tool","lane":"specific","trade":"Roofer","mobile":true,"group":"Tools · Specific","name":"Roofline","biz":"Ackroyd Roofing","c":"#A33B22","sheet":"#F2E4E0","cInk":"#FFFFFF","cText":"#A33B22","short":"A postcode and seven taps draw the roof, then price it.","long":"A homeowner gives an outward code, a house type, a roof shape and a covering, and the page draws their roof from above with its dimensions, lists the tiles, battens, membrane and ridge it would take, and puts an estimate range at the top. The roofer's side of the same page holds every enquiry with the workings behind it, and a rates screen where changing the price of a tile re-prices the whole book as he types.","proves":"Somebody can find out what a re-roof costs at eleven at night without giving a stranger their address.","tags":["calculator","drawn SVG","lead capture"]},{"n":36,"slug":"roundsheet","kind":"tool","lane":"specific","trade":"Window cleaner","mobile":true,"group":"Tools · Specific","name":"Roundsheet","biz":"Nash Window Cleaning","c":"#0F6B93","sheet":"#DDEAF0","cInk":"#FFFFFF","cText":"#0F6B93","short":"The round in door order, with a DONE big enough for one thumb.","long":"Four rounds, 122 customers and a today list of 28 doors in the order he walks them. Marking a house done moves the running total, fills its dot on the route and lands in the money view the same second; a cash house stays on the list until he says whether he was paid. If it comes in wet, one button moves the rest of the sheet to the next working day and shifts everything behind it.","proves":"The whole round fits on the phone in his hand while he is stood at the gate.","tags":["round manager","one-handed","drawn route"]}];